def classify_action(top, replacement):
    if replacement == (top,):
        return "KEEP", None
    if not replacement:
        return "POP", None
    if len(replacement) == 2 and replacement[0] == top:
        return "PUSH", replacement[1]
    require(len(replacement) == 1, f"Unsupported replacement {replacement}")
    return "REPLACE", replacement[0]


def mask_expression(tops):
    allowed = set(tops)
    if allowed == set(SYMBOLS):
        return "ALL_STACK_TOPS"
    if allowed == {"EMPTY", "DOLLAR_EXPR"}:
        return "CODE_TOPS"
    missing = set(SYMBOLS) - allowed
    if len(missing) == 1:
        return f"ALL_STACK_TOPS & ~TOP(STACK_{next(iter(missing))})"
    return " | ".join(f"TOP(STACK_{symbol})" for symbol in SYMBOLS if symbol in allowed)


